const OR_KEY = "YOUR_OPENROUTER_API_KEY";
const SYSTEM_PROMPT = "You qualify LinkedIn leads for a service helping US/Canadian companies enter the French/European market.\n\nQualify YES only if the person has commercial decision power (Founder, Co-Founder, CEO, President, Owner, VP, Head of Sales) at a company based in the US or Canada, in SaaS/software, beauty/cosmetics, retail, or fashion.\n\nQualify NO if: non-decision-making role (Growth Manager, Marketing Manager, etc.), clearly micro/freelance structure with no visible team, company outside US/Canada, profile marked Open to Work, industry outside SaaS/beauty/retail/fashion.\n\nReply ONLY in strict JSON, no surrounding text: {\"icp\": \"oui\" or \"non\", \"raison\": \"1 short sentence in French explaining why\"}";

async function classify(p) {
  const bio = (p.headline || '') + (p.locationText ? ' | Location: ' + p.locationText : '') + ((p.currentPosition && p.currentPosition[0] && p.currentPosition[0].description) ? ' | ' + p.currentPosition[0].description : '');
  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://openrouter.ai/api/v1/chat/completions',
      headers: { 'Authorization': 'Bearer ' + OR_KEY, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: 'anthropic/claude-haiku-4.5',
        messages: [
          { role: 'system', content: SYSTEM_PROMPT },
          { role: 'user', content: 'Name: ' + (p.firstName || '') + ' ' + (p.lastName || '') + '\nBio: ' + bio }
        ],
        temperature: 0.1,
        max_tokens: 150
      }),
      json: true,
    });
    const content = (resp.choices && resp.choices[0] && resp.choices[0].message.content) || '';
    const match = content.match(/\{[\s\S]*\}/);
    if (match) {
      const parsed = JSON.parse(match[0]);
      return { icp: (parsed.icp || '').toLowerCase().trim() === 'oui' ? 'oui' : 'non', raison: parsed.raison || '' };
    }
  } catch (e) {}
  return { icp: 'non', raison: '' };
}

const items = $input.all();
const out = [];
for (const item of items) {
  const p = item.json;
  const result = await classify.call(this, p);
  if (result.icp !== 'oui') continue;
  const pos = (p.currentPosition && p.currentPosition[0]) || {};
  const bio = (p.headline || '') + (pos.description ? ' | ' + pos.description : '');
  out.push({
    json: {
      id: p.id,
      name: (p.firstName || '') + ' ' + (p.lastName || ''),
      linkedinUrl: p.linkedinUrl,
      publicIdentifier: (p.linkedinUrl || '').match(/linkedin\.com\/in\/([^/?]+)/)?.[1] || '',
      headline: p.headline || '',
      bio: bio,
      company: pos.companyName || '',
      companyLinkedinUrl: pos.companyLinkedinUrl || '',
      icpMatch: 'oui',
      raisonIcp: result.raison,
      targetAccountName: p.targetAccountName,
      targetAccountId: p.targetAccountId
    }
  });
}
return out;

